<script setup lang="ts">
import PmsFormDialog from './PmsFormDialog.vue';import {ref,onMounted} from 'vue';import {pmsApi} from './api';const props=defineProps<{csrf?:string}>();const emit=defineEmits(['close']);const user=ref<any>(null),error=ref(''),busy=ref(false),photo=ref<File|null>(null),current=ref(''),password=ref(''),confirmation=ref('');onMounted(async()=>{try{user.value=(await pmsApi('profile')).data.user;}catch(e){error.value=(e as Error).message;}});async function save(){busy.value=true;error.value='';try{const f=new FormData();f.append('name',user.value.name);if(photo.value)f.append('profile_img',photo.value);if(password.value){f.append('current-password',current.value);f.append('new-password',password.value);f.append('repeat-password',confirmation.value);}await pmsApi('profile',props.csrf,'POST',f);emit('close');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script><template><PmsFormDialog title="Profile" wide centered @close="emit('close')"><form class="pms-reference-form" @submit.prevent="save"><p v-if="error" class="notice admin-error">{{error}}</p><template v-if="user"><img v-if="user.profile_img" class="pms-project-image" :src="user.profile_img" alt="Profile"><label>Name<input v-model="user.name" maxlength="255" required></label><label>Email<input :value="user.email" readonly></label><label class="full-width">Update Profile Image<input type="file" accept="image/*" @change="photo=($event.target as HTMLInputElement).files?.[0]||null"></label><h6 class="full-width">Change password if you want</h6><label class="full-width">Current Password<input v-model="current" type="password" autocomplete="current-password"></label><label>New password<input v-model="password" type="password" minlength="6" autocomplete="new-password"></label><label>Repeat password<input v-model="confirmation" type="password" autocomplete="new-password"></label></template><div class="editor-actions"><button class="button primary" :disabled="busy||!user">{{busy?'Saving...':'Update Profile'}}</button><button type="button" class="button" @click="emit('close')">Cancel</button></div></form></PmsFormDialog></template>